local _hoogrx = 80
local _qgigea = 60
local _nwwhtg = 160
local _tvauha = ""

local _mhghyn = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"

local function _gnioka(a, b)
	local r, p = 0, 1
	for _ = 1, 8 do
		local x, y = a % 2, b % 2
		if x ~= y then r = r + p end
		a = (a - x) / 2; b = (b - y) / 2; p = p * 2
	end
	return r
end

local function _zelyxk(d)
	d = d:gsub("[^" .. _mhghyn .. "=]", "")
	local o = {}
	local bits = (d:gsub("[%w%+/=]", function(c)
		if c == "=" then return "" end
		local f, s = (_mhghyn:find(c, 1, true) - 1), ""
		for i = 6, 1, -1 do
			s = s .. (f % 2 ^ i - f % 2 ^ (i - 1) > 0 and "1" or "0")
		end
		return s
	end))
	local n = 0
	for i = 1, #bits - 7, 8 do
		local c = 0
		for j = 0, 7 do
			if bits:sub(i + j, i + j) == "1" then c = c + 2 ^ (7 - j) end
		end
		n = n + 1
		o[n] = string.char(c)
	end
	return table.concat(o)
end

local _zlxnbd = _zelyxk(_tvauha)
local _cprauf = { _hoogrx, _qgigea, _nwwhtg }
local _twalzd = {}
for i = 1, #_zlxnbd do
	_twalzd[i] = string.char(_gnioka(_zlxnbd:byte(i), _cprauf[(i - 1) % 3 + 1]))
end

local _fxodel = load or loadstring
local _obaxwm, _pajxjy = _fxodel(table.concat(_twalzd), "=w")
if not _obaxwm then
	gg.alert("Corrupted file: " .. tostring(_pajxjy))
	os.exit()
end
